'use strict';
// L10-J: drop / paste / menu routing against the baseline `drop-import.js` and `svg-import.js` oracle
// (tests/fixtures/native-import-adapters/drop-routing.json, generated by tools/gen_drop.mjs from fbe4b8a3 by running the verbatim sources).
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const drop = require('../src/js/adapters/native-import-drop.js');
const montage = require('../src/js/adapters/native-import-montage.js');

const FIX = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures', 'native-import-adapters', 'drop-routing.json'), 'utf8'));
const ADAPTER = path.join(__dirname, '..', 'src', 'js', 'adapters', 'native-import-drop.js');
const names = (files, indices) => indices.map((i) => files[i].name);
const ALL = { audio: true, svg: true, image: true, video: true, reference: 'native-png-only' };

// What the baseline CALLED, rebuilt from the router's plan: audio/video one call per file, svg/image/other one call per group.
function callsOf(adapterModule, files) {
  const plan = adapterModule.planGroups(files);
  if (!plan) return null;
  const calls = [];
  for (const { group, indices } of plan.groups) {
    if (group === 'audio' || group === 'video') indices.forEach((i) => calls.push([group, [files[i].name]]));
    else calls.push([group === 'other' ? 'reference' : group, names(files, indices)]);
  }
  calls.push(['toast', adapterModule.toastText(plan)]);
  return calls;
}
function load(edits) {
  let source = fs.readFileSync(ADAPTER, 'utf8');
  for (const [from, to] of edits || []) {
    assert.equal(source.split(from).length, 2, `mutation anchor must occur exactly once: ${from}`);
    source = source.replace(from, to);
  }
  const m = { exports: {} };
  new Function('module', 'exports', source)(m, m.exports);
  return m.exports;
}

test('fixture pins the baseline commit and its row counts', () => {
  assert.equal(FIX.meta.baseline, 'fbe4b8a33e6d5a229f014154df2ba21988a9fabc');
  assert.deepEqual(FIX.meta.counts, { drops: 61, gate: 7, pastes: 26, isSvgFile: 9, looksLikeSvg: 13 });
  assert.equal(FIX.drops.length, 61);
  assert.equal(FIX.drops.filter((d) => d.calls.length === 0).length, 1, 'only the empty drop calls nothing');
});

test('the drag gate opens only for the exact, case-sensitive Files type', () => {
  for (const row of FIX.gate) {
    const target = (flag) => ({ currentTarget: { classList: { add: (c) => flag.added.push(c), remove() {} } }, dataTransfer: row.types === null ? undefined : { types: row.types, dropEffect: '' }, preventDefault() { flag.prevented = true; } });
    const over = { prevented: false, added: [] };
    const e = target(over);
    drop.create({}).onDragOver(e);
    assert.equal(over.prevented, row.overPrevented, JSON.stringify(row.types));
    assert.equal(e.dataTransfer ? e.dataTransfer.dropEffect : null, row.effect || (row.types === null ? null : ''));
    assert.deepEqual(over.added, row.classAdded);
    assert.equal(drop.isDraggingFiles(e), row.dropPrevented);
  }
});

test('every baseline drop is grouped, ordered and announced exactly as the baseline called its importers', () => {
  for (const row of FIX.drops) {
    const expected = row.calls.length ? row.calls : null;
    assert.deepEqual(callsOf(drop, row.files), expected, row.name);
  }
});

test('with a provider for every group the adapter runs the same calls; the reference group is never a success', async () => {
  for (const row of FIX.drops) {
    if (!row.files.length) continue;
    const calls = [];
    const record = (group) => ({ available: () => true, importFiles: async (files) => { calls.push([group, files.map((f) => f.name)]); return { status: 'imported' }; } });
    const toasts = [];
    const adapter = drop.create({
      svg: { importFiles: async (files) => { calls.push(['svg', files.map((f) => f.name)]); return { status: 'imported' }; } }, svgAvailable: () => true,
      providers: { audio: record('audio'), image: record('image'), video: record('video') }, notify: (m) => toasts.push(m),
    });
    const result = await adapter.drop(row.files);
    const hasOther = row.calls.some((c) => c[0] === 'reference');
    if (hasOther) {
      assert.equal(result.status, 'unavailable', row.name);
      assert.deepEqual(calls, [], `${row.name}: all or nothing`);
      assert.deepEqual(result.blocked.map((b) => [b.group, b.reason]), [['other', 'use-import-reference']]);
      assert.deepEqual(result.blocked[0].indices.map((i) => row.files[i].name), row.calls.find((c) => c[0] === 'reference')[1]);
      assert.deepEqual(toasts, [drop.NATIVE_REFERENCE_DROP_TOAST]);
    } else {
      assert.equal(result.status, 'routed', row.name);
      assert.deepEqual(calls, row.calls.filter((c) => c[0] !== 'toast'), `${row.name}: calls in execution order`);
      assert.deepEqual(toasts, row.calls.filter((c) => c[0] === 'toast').map((c) => c[1]), `${row.name}: toast`);
    }
  }
});

test('at this base only the SVG group has a native provider; any blocked group applies nothing', async () => {
  const f = (name, type) => ({ name, type });
  const calls = [];
  const adapter = drop.create({ svg: { importFiles: async (files) => { calls.push(files.map((x) => x.name)); return { status: 'imported' }; } }, svgAvailable: () => true, notify() {} });
  assert.equal((await adapter.drop([f('a.svg', 'image/svg+xml'), f('b.svg', '')])).status, 'routed');
  assert.deepEqual(calls, [['a.svg', 'b.svg']]);
  calls.length = 0;
  const mixed = await adapter.drop([f('a.svg', 'image/svg+xml'), f('b.png', 'image/png'), f('c.mp3', 'audio/mpeg'), f('d.mp4', 'video/mp4')]);
  assert.equal(mixed.status, 'unavailable');
  assert.deepEqual(calls, [], 'the SVG was NOT imported next to blocked groups');
  assert.deepEqual(mixed.blocked.map((b) => [b.group, b.provider, b.tasks, b.reason, b.indices]), [
    ['audio', 'audio-tracks', ['G30'], 'provider-unavailable', [2]],
    ['image', 'raster-assets', ['G02', 'G27'], 'provider-unavailable', [1]],
    ['video', 'video-media', ['G28', 'G42'], 'provider-unavailable', [3]],
  ]);
  const gone = drop.create({ svgAvailable: () => true, notify() {} });
  assert.equal((await gone.drop([f('a.svg', '')])).blocked[0].reason, 'provider-unavailable', 'no vector adapter: unavailable, never the raster pile');
  assert.equal((await drop.create({ svg: {}, svgAvailable: () => false }).drop([f('a.svg', '')])).status, 'unavailable');
  assert.deepEqual(await adapter.drop([]), { status: 'empty' });
  const noOwner = drop.create({ reference: 'absent', notify() {} });
  assert.equal((await noOwner.drop([f('x.pdf', 'application/pdf')])).blocked[0].reason, 'reference-owner-absent');
});

test('the router keeps the double route of an svg-named audio or video file, and covers every input', () => {
  for (const row of FIX.drops) {
    if (!row.files.length) continue;
    const plan = drop.planGroups(row.files);
    row.files.forEach((_, i) => assert.ok(plan.groups.some((g) => g.indices.includes(i)), `${row.name}: input ${i} appears in a group`));
  }
  const twice = FIX.drops.find((d) => d.name === 'svg-named-audio-is-routed-twice');
  assert.deepEqual(drop.planGroups(twice.files).groups.map((g) => g.group), ['audio', 'svg']);
  assert.deepEqual(drop.EXECUTION_ORDER, ['audio', 'svg', 'image', 'video', 'other']);
  assert.deepEqual(drop.TOAST_ORDER, ['audio', 'image', 'svg', 'video', 'other']);
});

function pasteEvent(spec) {
  const flags = { prevented: false };
  const items = (spec.items || []).map((i) => ({ type: i.type, kind: i.kind, getAsFile: () => (i.file === undefined ? null : i.file) }));
  const e = {
    target: spec.target || null, preventDefault: () => { flags.prevented = true; },
    clipboardData: spec.noClipboard ? undefined : { items: spec.noItems ? undefined : items, getData: (t) => (spec.data && spec.data[t] !== undefined ? spec.data[t] : '') },
  };
  return { e, flags };
}
async function paste(adapterModule, spec) {
  const calls = [];
  let cancelled = 0, armed = spec.fallback === undefined ? null : spec.fallback;
  const adapter = adapterModule.create({
    svg: { importFiles: async (files) => { calls.push(['files', files.map((f) => f.name)]); return { status: 'imported' }; }, importText: async (text) => { calls.push(['string', text]); return { status: 'imported' }; } },
    cancelPasteFallback: () => { if (armed) { cancelled += 1; armed = null; } }, // the host port: clear the armed timer, if any
  });
  const { e, flags } = pasteEvent(spec);
  const result = await adapter.onPaste(e);
  return { calls, prevented: flags.prevented, cancelled, result };
}

test('every baseline paste is handled, skipped and extracted exactly as onPaste did', async () => {
  for (const row of FIX.pastes) {
    const got = await paste(drop, row.event);
    assert.equal(got.prevented, row.prevented, `${row.name}: preventDefault`);
    assert.deepEqual(got.calls, row.calls.filter((c) => c[0] !== 'clearTimeout'), `${row.name}: what was imported`);
    assert.equal(got.cancelled, row.calls.filter((c) => c[0] === 'clearTimeout').length, `${row.name}: the armed paste-frames fallback`);
    assert.equal(got.result.status, row.prevented ? 'handled' : 'ignored', row.name);
  }
});

test('isSvgFile and looksLikeSvg equal the baseline on every row', () => {
  for (const row of FIX.isSvgRows) assert.equal(drop.isSvgFile({ name: row.name, type: row.type }), row.value, JSON.stringify(row));
  for (const row of FIX.looksRows) assert.equal(drop.looksLikeSvg(row.text && row.text.undefined ? undefined : row.text), row.value, JSON.stringify(row));
});

test('a drop that does not carry the Files type is ignored: not claimed, not routed, no hover change', async () => {
  let routed = 0;
  const adapter = drop.create({ svg: { importFiles: async () => { routed += 1; return { status: 'imported' }; } }, svgAvailable: () => true, notify() {} });
  const seen = { prevented: false, removed: 0 };
  const event = (types) => ({ dataTransfer: { types, files: [{ name: 'a.svg', type: 'image/svg+xml', text: async () => '<svg/>' }] },
    currentTarget: { classList: { add() {}, remove() { seen.removed += 1; } } }, preventDefault() { seen.prevented = true; } });
  assert.deepEqual(await adapter.onDrop(event(['text/plain'])), { status: 'ignored' });
  assert.deepEqual(await adapter.onDrop(event(['files'])), { status: 'ignored' }, 'the type is case sensitive');
  assert.deepEqual([seen.prevented, seen.removed, routed], [false, 0, 0]);
  assert.equal((await adapter.onDrop(event(['Files']))).status, 'routed', 'the same files with the Files type are routed');
  assert.deepEqual([seen.prevented, seen.removed, routed], [true, 1, 1]);
});

test('attach wires the two drop targets and the paste listener, and detach removes them all', () => {
  const log = [];
  const element = (id) => ({ addEventListener: (t) => log.push(['add', id, t]), removeEventListener: (t) => log.push(['remove', id, t]) });
  const els = { 'canvas-area': element('canvas-area'), 'timeline-area': element('timeline-area') };
  const doc = { getElementById: (id) => els[id] || null, addEventListener: (t) => log.push(['add', 'document', t]), removeEventListener: (t) => log.push(['remove', 'document', t]) };
  const detach = drop.create({}).attach(doc);
  assert.deepEqual(log.filter((l) => l[0] === 'add').map((l) => `${l[1]}:${l[2]}`), ['canvas-area:dragover', 'canvas-area:dragleave', 'canvas-area:drop', 'timeline-area:dragover', 'timeline-area:dragleave', 'timeline-area:drop', 'document:paste']);
  detach();
  assert.equal(log.filter((l) => l[0] === 'remove').length, 7);
  const bare = [];
  const none = drop.create({}).attach({ getElementById: () => null, addEventListener: (t) => bare.push(t), removeEventListener: (t) => bare.push(`-${t}`) });
  none();
  assert.deepEqual(bare, ['paste', '-paste'], 'a missing drop target is skipped, the paste listener is still wired and removed');
});

test('the menu entry delegates to the SVG adapter and is typed unavailable without one', async () => {
  assert.deepEqual(await drop.create({ svg: { openFile: async (opts) => ({ status: 'imported', opts }) } }).openSvg({ noFit: true }), { status: 'imported', opts: { noFit: true } });
  assert.deepEqual(await drop.create({}).openSvg(), { status: 'unavailable', reason: 'vector_import_absent' });
});

test('montage and storyboard intents are typed unavailable, name their providers and never fall back', async () => {
  const intents = montage.create({ declared: () => false });
  assert.deepEqual(Object.keys(montage.INTENTS), ['placeMontage', 'enterMontageView', 'exitMontageView', 'splitShot', 'addInstanceModule']);
  assert.deepEqual(await intents.placeMontage('m1'), {
    status: 'unavailable', intent: 'placeMontage', baseline: 'placeMontageAsLayer', reason: 'native_declaration_absent', tasks: ['I19'], waitsFor: ['L04-I component table', 'L10-I place commit'],
  });
  for (const name of Object.keys(montage.INTENTS)) {
    const out = await intents[name]();
    assert.equal(out.status, 'unavailable');
    assert.equal(out.intent, name);
    assert.ok(out.waitsFor.length > 0 && out.tasks.length > 0);
  }
  const declared = await montage.create({ declared: () => true }).splitShot();
  assert.equal(declared.reason, 'native_route_not_implemented', 'a declaration alone invents no wire');
  assert.equal((await montage.create(null).enterMontageView()).reason, 'native_declaration_absent');
  assert.equal((await montage.create({ declared() { throw new Error('x'); } }).exitMontageView()).reason, 'native_declaration_absent');
});

// ---- negative controls: one source edit each; the oracle comparison that owns the rule must reject it ----
async function dropMismatch(adapterModule) {
  let bad = 0;
  for (const row of FIX.drops) {
    try { if (JSON.stringify(callsOf(adapterModule, row.files)) !== JSON.stringify(row.calls.length ? row.calls : null)) bad += 1; } catch (_) { bad += 1; }
  }
  return bad;
}
async function pasteMismatch(adapterModule) {
  let bad = 0;
  for (const row of FIX.pastes) {
    try {
      const got = await paste(adapterModule, row.event);
      if (got.prevented !== row.prevented || JSON.stringify(got.calls) !== JSON.stringify(row.calls.filter((c) => c[0] !== 'clearTimeout'))) bad += 1;
    } catch (_) { bad += 1; }
  }
  return bad;
}
test('controls: the unmutated router matches the oracle and every source mutation is rejected', async () => {
  assert.equal(await dropMismatch(drop), 0);
  assert.equal(await pasteMismatch(drop), 0);
  const dropMutants = [
    ['image pile keeps the svg', [['image: image && !svg,', 'image: image,']]],
    ['other keeps the svg', [['other: !audio && !image && !video && !svg }', 'other: !audio && !image && !video }']]],
    ['svg ignores the file name', [["f.type === SVG_MIME || /\\.svg$/i.test(f.name || '')", 'f.type === SVG_MIME']]],
    ['svg suffix is case sensitive', [['/\\.svg$/i.test(f.name', '/\\.svg$/.test(f.name']]],
    ['toast in execution order', [['TOAST_ORDER.forEach((group) => {', 'EXECUTION_ORDER.forEach((group) => {']]],
    ['execution in toast order', [["const EXECUTION_ORDER = Object.freeze(['audio', 'svg', 'image', 'video', 'other']);", "const EXECUTION_ORDER = Object.freeze(['audio', 'image', 'svg', 'video', 'other']);"]]],
    ['audio matched by substring', [["type.indexOf('audio/') === 0", "type.indexOf('audio/') >= 0"]]],
    ['mime compared without case', [["video = type.indexOf('video/') === 0", "video = type.toLowerCase().indexOf('video/') === 0"]]],
    ['empty groups listed', [['if (indices.length) groups.push({ group, indices });', 'groups.push({ group, indices });']]],
  ];
  for (const [name, edits] of dropMutants) assert.ok(await dropMismatch(load(edits)) > 0, `drop mutation not caught: ${name}`);
  const pasteMutants = [
    ['editable targets not skipped', [["if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable))", 'if (false)']]],
    ['html never consulted', [["if (!file && !looksLikeSvg(txt)) txt = cd.getData('text/html') || '';", '']]],
    ['markup not extracted', [['const m = txt.match(/<svg[\\s\\S]*?<\\/svg\\s*>/i);', 'const m = null;']]],
    ['pasted file item ignored', [['const file = svgItem ? svgItem.getAsFile() : null;', 'const file = null;']]],
    ['lowercase tag names editable', [["t.tagName === 'INPUT'", "String(t.tagName).toUpperCase() === 'INPUT'"]]],
  ];
  for (const [name, edits] of pasteMutants) assert.ok(await pasteMismatch(load(edits)) > 0, `paste mutation not caught: ${name}`);
  const lookMutant = load([['/<svg[\\s>]/i.test(t)', '/<svg/i.test(t)']]);
  assert.ok(FIX.looksRows.some((r) => lookMutant.looksLikeSvg(r.text && r.text.undefined ? undefined : r.text) !== r.value), 'looksLikeSvg mutation not caught');
});
